-- On indexe les colonnes filtrées, jointes ou triées fréquemment
CREATE INDEX idx_enrollments_user ON enrollments(user_id);

-- Index composite : l'ordre des colonnes compte (préfixe utilisable)
CREATE INDEX idx_enr_user_roadmap ON enrollments(user_id, roadmap_id);

-- CREATE INDEX pose un verrou qui bloque les écritures.
-- CONCURRENTLY construit l'index sans bloquer (plus lent, hors transaction).
CREATE INDEX CONCURRENTLY idx_enr_activity
  ON enrollments (last_activity_at DESC);

-- Rafraîchir les stats après un gros chargement :
ANALYZE enrollments;
